use crate::*;
use crate::owned::tree;
use crate::{DslValue,Number,RetainedWorkOutcome,retained_clone::RetainedCloneSource};
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
trait ActualError:std::fmt::Debug{fn receipt(&self)->RetainedCloneProgress;}
impl ActualError for ValueError{fn receipt(&self)->RetainedCloneProgress{self.retained_progress()}}
impl ActualError for crate::OriginalReceivingPrimary{fn receipt(&self)->RetainedCloneProgress{self.retained_progress()}}
fn post<E:ActualError>(bank:&mut RetainedCloneGrant,fuel:&mut u64,turn:RetainedWorkOutcome<RetainedCloneStep,E>)->Result<RetainedCloneStep,E>{let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.receipt()};debit(bank,fuel,p,turn.work);turn.result}
#[test]fn actual_native_scalar_denial_read_error_and_close_keep_independent_work(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();
 let before=fuel;let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(DslValue::Number(Number::UInt(row["input"].as_u64().unwrap())),&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w,p,work,_,_|debit(w.0,w.1,p,work))};assert_eq!(before-fuel,row["sourceAdmissionWork"].as_u64().unwrap());let pointer=std::ptr::from_ref(source.borrow().get());let(mut receiver,heap)=crate::observe_retirement_allocations(tree::NativeScalarReceiver::<DslValue,u64>::new);assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(s["capacityBytes"].as_u64().unwrap()as usize,&mut callback);
 for expected in["bindingWork","readWork"]{let d=receiver.demands(source.borrow(),4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,..bank};for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=crate::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,row["deniedWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(std::ptr::from_ref(source.borrow().get()),pointer);}let(turn,heap)=crate::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,g));assert_eq!(turn.work,row[expected].as_u64().unwrap());let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,turn).unwrap();}
 let turn=receiver.take(RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(value,p)=turn.result.unwrap().unwrap();assert_eq!(serde_json::to_value(value).unwrap(),row["input"]);debit(&mut bank,&mut fuel,p,work);receiver.begin_close();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let turn=receiver.close_step(RetainedCloneGrant{maximum_items:1,..bank});assert!(turn.work<=1);post(&mut bank,&mut fuel,turn).unwrap();}assert!(receiver.terminal_is_empty());assert_eq!(receiver.close_step(Default::default()).work,row["cachedCloseWork"].as_u64().unwrap());drop(receiver);
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}let turn=source.close_step(RetainedCloneGrant{maximum_items:1,..bank});assert!(turn.work<=1);post(&mut bank,&mut fuel,turn).unwrap();}assert!(source.terminal_is_empty());drop(source);
 let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(DslValue::Bool(false),&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w,p,work,_,_|debit(w.0,w.1,p,work))};let mut receiver=tree::NativeScalarReceiver::<DslValue,u64>::new();let turn=receiver.advance(source.borrow(),&mut control,4096,RetainedCloneGrant{maximum_items:1,..bank});post(&mut bank,&mut fuel,turn).unwrap();let turn=receiver.advance(source.borrow(),&mut control,4096,RetainedCloneGrant{maximum_items:1,..bank});assert_eq!(turn.work,row["invalidReadWork"].as_u64().unwrap());let error=post(&mut bank,&mut fuel,turn).unwrap_err();assert_eq!(error.primary.as_ref().unwrap().kind,crate::ValueRefusalKind::InvalidValue);assert!(!receiver.output_ready());receiver.begin_close();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let turn=receiver.close_step(RetainedCloneGrant{maximum_items:1,..bank});post(&mut bank,&mut fuel,turn).unwrap();}assert!(receiver.terminal_is_empty());drop(receiver);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}let turn=source.close_step(RetainedCloneGrant{maximum_items:1,..bank});post(&mut bank,&mut fuel,turn).unwrap();}assert!(source.terminal_is_empty());
}
